$('board').addEventListener('pointerdown',e=>{if(e.button!==0)return;const target=e.target.closest('[data-id]');if(!target){if(!$('multiToggle').checked&&!e.shiftKey&&!e.ctrlKey&&!e.metaKey){selectOnly(null);renderInspector();renderBoard();}return;}const id=target.dataset.id,additive=e.shiftKey||e.ctrlKey||e.metaKey||$('multiToggle').checked;if(additive){toggleSelected(id);renderInspector();renderBoard();e.preventDefault();return;}if(!selection.has(id))selectOnly(id);else selected=id;const i=item(),p=point(e);$('board').focus({preventScroll:true});if(!i.locked){const moving=selectedItems().filter(o=>!o.locked&&!o.storedIn).map(o=>({id:o.id,x:o.x,y:o.y,...bounds(o)}));drag={px:p.x,py:p.y,moving,started:false,original:JSON.stringify(project),pointer:e.pointerId};$('board').setPointerCapture(e.pointerId);}else toast('Position locked. Choose Unlock to edit in Details.');renderInspector();renderBoard();e.preventDefault();});
$('board').addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const p=point(e);let dx=p.x-drag.px,dy=p.y-drag.py;if($('snapToggle').checked){dx=Math.round(dx*2)/2;dy=Math.round(dy*2)/2;}const minX=Math.min(...drag.moving.map(i=>i.x)),minY=Math.min(...drag.moving.map(i=>i.y)),maxX=Math.max(...drag.moving.map(i=>i.x+i.w)),maxY=Math.max(...drag.moving.map(i=>i.y+i.h));dx=Math.max(-minX,Math.min(layout().room.width-maxX,dx));dy=Math.max(-minY,Math.min(layout().room.length-maxY,dy));let changed=false;for(const original of drag.moving){const i=layout().items.find(o=>o.id===original.id),x=fmtRaw(original.x+dx),y=fmtRaw(original.y+dy);if(i.x!==x||i.y!==y){i.x=x;i.y=y;changed=true;}}if(changed){drag.started=true;renderBoard();}});
function endDrag(e){if(!drag||drag.pointer!==e.pointerId)return;if(drag.started){undo.push(drag.original);if(undo.length>60)undo.shift();redo=[];persist();}drag=null;render();}
$('board').addEventListener('pointerup',endDrag);$('board').addEventListener('pointercancel',e=>{if(!drag||drag.pointer!==e.pointerId)return;project=JSON.parse(drag.original);drag=null;render();});
document.addEventListener('keydown',e=>{if(e.target.isContentEditable||e.target.closest('[role="textbox"]')||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();history(!e.shiftKey);return;}if(e.key==='Escape'){selectOnly(null);renderInspector();renderBoard();return;}if(!selection.size)return;if(e.key.toLowerCase()==='r'&&!mod){e.preventDefault();rotate();return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();return;}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const moving=selectedItems().filter(i=>!i.locked);if(!moving.length)return;e.preventDefault();const d=e.shiftKey?2:$('snapToggle').checked?.5:.1;change(()=>{for(const i of moving){const x=i.storedIn?'storageX':'x',y=i.storedIn?'storageY':'y';if(e.key==='ArrowLeft')i[x]-=d;if(e.key==='ArrowRight')i[x]+=d;if(e.key==='ArrowUp')i[y]-=d;if(e.key==='ArrowDown')i[y]+=d;i[x]=fmtRaw(i[x]);i[y]=fmtRaw(i[y]);}});}});
