$('inspectorContent').addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action,i=item(),restore=e.target.closest('[data-restore]'),insert=e.target.closest('[data-add-corner]'),remove=e.target.closest('[data-remove-corner]');if(restore){change(()=>delete layout().items.find(o=>o.id===restore.dataset.restore).storedIn);return;}if(a==='store'){change(()=>selectedItems().filter(isEquipment).forEach(o=>storeEquipment(layout().items,o)));toast('Equipment moved to the storage inventory.');return;}if(i?.category!=='area')return;if(a==='hart-contour'&&!i.locked){change(()=>Object.assign(i,areaFromWorldPoints(i,[[50,48],[layout().room.innerWidth||73,48],[layout().room.innerWidth||73,layout().room.length],[33.5,layout().room.length],[33.5,76],[38.5,66],[41.5,62]])));toast('Cardio contour follows the current Hart sketch. Edit corners as measurements change.');}if(a==='contour'){cornerMode=!cornerMode;labelMode=false;if(cornerMode&&!i.vertices)change(()=>i.vertices=[[0,0],[1,0],[1,1],[0,1]]);else{renderInspector();renderBoard();}}if(a==='label-mode'){labelMode=!labelMode;cornerMode=false;renderInspector();renderBoard();}if(a==='reset-label')change(()=>i.label={x:.5,y:.5,rotation:0});if((insert||remove)&&!i.locked){const v=structuredClone(i.vertices||[[0,0],[1,0],[1,1],[0,1]]),n=Number((insert||remove).dataset[insert?'addCorner':'removeCorner']);if(insert){if(v.length>=60)return toast('Maximum 60 corners.');const next=v[(n+1)%v.length];v.splice(n+1,0,[(v[n][0]+next[0])/2,(v[n][1]+next[1])/2]);}else v.splice(n,1);if(simplePolygon(v))change(()=>i.vertices=v);else toast('That change would cross the contour.');}});
$('inspectorContent').addEventListener('change',e=>{const i=item();if(i?.category!=='area')return;const prop=e.target.dataset.labelProp;if(prop){if(!e.target.checkValidity()||e.target.value===''){renderInspector();return;}change(()=>{i.label??={x:.5,y:.5,rotation:0};i.label[prop]=Number(e.target.value)/(prop==='x'?i.width:prop==='y'?i.length:1);});}if(e.target.dataset.corner!==undefined){if(i.locked)return;const v=structuredClone(i.vertices),n=Number(e.target.dataset.corner),axis=Number(e.target.dataset.axis);v[n][axis]=Number(e.target.value)/(axis?i.length:i.width);if(e.target.value!==''&&e.target.checkValidity()&&simplePolygon(v))change(()=>i.vertices=v);else{toast('Use a valid corner that does not cross another edge.');renderInspector();}}});
// Layout deletion is behind a menu and a confirmation, and remains undoable.
const originalRender=render;
render=function(){originalRender();renderStorage();renderInventory();document.querySelectorAll('.layout-row').forEach(b=>{const wrapper=document.createElement('div');wrapper.className='layout-entry';b.replaceWith(wrapper);const menu=document.createElement('details');menu.className='layout-menu';const summary=document.createElement('summary');summary.textContent='•••';summary.title='Layout options';summary.setAttribute('aria-label','Options for '+b.querySelector('strong').textContent);const del=document.createElement('button');del.textContent='Delete layout…';del.dataset.deleteLayout=b.dataset.layout;del.disabled=project.layouts.length===1;if(del.disabled)del.title='Keep at least one layout. Create a blank layout first.';del.onclick=()=>{pendingDeleteLayout=b.dataset.layout;$('deleteLayoutMessage').textContent='Delete “'+project.layouts.find(l=>l.id===pendingDeleteLayout).name+'”?';menu.open=false;$('deleteLayoutDialog').showModal();};menu.append(summary,del);wrapper.append(b,menu);});};
// Capture gestures before the equipment move handler.
$('board').addEventListener('pointerdown',e=>{if(e.button!==0)return;const resize=e.target.closest('[data-resize]'),vertex=e.target.closest('[data-vertex]'),label=e.target.closest('[data-label]');const target=e.target.closest('[data-id]'),area=target&&layout().items.find(i=>i.id===target.dataset.id),empty=(!target||(area?.category==='area'&&!selection.has(area.id)&&!e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!$('multiToggle').checked))&&!resize&&!vertex&&!label;if(!empty&&!resize&&!vertex&&!label)return;e.preventDefault();e.stopImmediatePropagation();const i=item();if(!empty&&(!i||(i.locked&&!label)))return;const p=point(e);editGesture={type:empty?'pan':resize?'resize':vertex?'vertex':'label',handle:resize?.dataset.resize,index:Number(vertex?.dataset.vertex),original:i?structuredClone(i):null,snapshot:JSON.stringify(project),start:p,camera:{...camera},client:{x:e.clientX,y:e.clientY},targetId:target?.dataset.id,additive:e.shiftKey||e.ctrlKey||e.metaKey||$('multiToggle').checked,pointer:e.pointerId};$('board').setPointerCapture(e.pointerId);},true);
$('board').addEventListener('pointermove',e=>{const g=editGesture;if(!g||e.pointerId!==g.pointer)return;e.stopImmediatePropagation();e.preventDefault();const p=point(e);if(g.type==='pan'){const matrix=$('board').getScreenCTM();camera.x=g.camera.x-(e.clientX-g.client.x)/matrix.a;camera.y=g.camera.y-(e.clientY-g.client.y)/matrix.d;}else{const i=layout().items.find(i=>i.id===g.original.id),snap=n=>$('snapToggle').checked?Math.round(n*2)/2:n;if(g.type==='resize')Object.assign(i,resizeArea(g.original,g.handle,{x:snap(p.x),y:snap(p.y)}));if(g.type==='label'){const q=localPoint(i,p);i.label={x:Math.max(0,Math.min(1,q.x/i.width+.5)),y:Math.max(0,Math.min(1,q.y/i.length+.5)),rotation:i.label?.rotation||0};}if(g.type==='vertex'){const pts=itemPoints(g.original);pts[g.index]=[snap(p.x),snap(p.y)];const b=polygonBounds(pts);if(b.w>=.5&&b.h>=.5&&b.w<=100&&b.h<=100&&simplePolygon(pts))Object.assign(i,areaFromWorldPoints(g.original,pts));}}renderBoard();},true);
function endEdit(e){const g=editGesture;if(!g||g.pointer!==e.pointerId)return;e.stopImmediatePropagation();if(e.type==='pointercancel'){project=JSON.parse(g.snapshot);camera=g.camera;}else if(g.type==='pan'&&Math.hypot(e.clientX-g.client.x,e.clientY-g.client.y)<4){camera=g.camera;if(g.targetId||!g.additive)selectOnly(g.targetId||null);}else if(g.type!=='pan'&&JSON.stringify(project)!==g.snapshot){undo.push(g.snapshot);if(undo.length>60)undo.shift();redo=[];persist();}editGesture=null;render();}
$('board').addEventListener('pointerup',endEdit,true);$('board').addEventListener('pointercancel',endEdit,true);
$('board').addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();const before=point(e);zoom=Math.max(.5,Math.min(12,zoom*Math.exp(-e.deltaY*.002)));renderBoard();const after=point(e);camera.x+=before.x-after.x;camera.y+=before.y-after.y;renderBoard();},{passive:false});
// Map-only print sheets with a legend for the equipment in each crop.
function openPrint(){const r=layout().room;$('printScope').innerHTML='<option value="whole">Entire gym</option><option value="view">Current view</option>'+layout().items.filter(i=>i.category==='area').map(i=>`<option value="${esc(i.id)}">Area: ${esc(i.name)}</option>`).join('')+'<option value="custom">Custom rectangle</option>';$('customPrintFields').innerHTML=[['x',0],['y',0],['w',r.width],['h',r.length]].map(([key,v])=>`<label>${({x:'Left X',y:'Top Y',w:'Width',h:'Length'})[key]} · ft<input id="print-${key}" type="number" step="any" min="${['w','h'].includes(key)?'.5':'-1000'}" max="1000" value="${v}"></label>`).join('');$('customPrintFields').hidden=true;$('printDialog').showModal();}
$('printScope').onchange=()=>{$('customPrintFields').hidden=$('printScope').value!=='custom';};$('cancelPrint').onclick=()=>$('printDialog').close();
function printRegion(){const scope=$('printScope').value,r=layout().room;if(scope==='whole')return {x:-2,y:-2,w:r.width+4,h:r.length+4};if(scope==='view'){const v=$('board').viewBox.baseVal;return {x:v.x,y:v.y,w:v.width,h:v.height};}if(scope==='custom'){const o=Object.fromEntries(['x','y','w','h'].map(k=>[k,Number($('print-'+k).value)]));if(!['x','y','w','h'].every(k=>$('print-'+k).value!==''&&$('print-'+k).checkValidity()))throw Error('Enter a valid print rectangle.');return o;}return polygonBounds(itemPoints(layout().items.find(i=>i.id===scope)));}
$('previewPrint').onclick=()=>{try{const region=printRegion(),n=Number($('printSheets').value),tiles=printTiles(region,n,n),clone=$('board').cloneNode(true);clone.removeAttribute('id');clone.removeAttribute('tabindex');clone.style.width='100%';clone.style.height='100%';clone.querySelectorAll('.area-handles').forEach(e=>e.remove());clone.querySelectorAll('[aria-pressed="true"]').forEach(g=>{g.setAttribute('aria-pressed','false');g.querySelectorAll(':scope > rect,:scope > g > path,:scope > g > text').forEach(e=>{if(e.parentNode===g||e.textContent==='F')e.remove();});});const title=$('printScope').selectedOptions[0].textContent;let pages='';for(const [index,tile] of tiles.entries()){clone.setAttribute('viewBox',`${tile.x} ${tile.y} ${tile.w} ${tile.h}`);const equipment=layout().items.filter(i=>!i.storedIn&&!['area','obstacle'].includes(i.category)&&intersects(bounds(i),tile)),groups=new Map();for(const i of equipment){const name=i.name.replace(/\s+(copy|\d+)$/,''),key=[i.kind,name,i.width,i.length].join('|');if(!groups.has(key))groups.set(key,{...i,name,count:0});groups.get(key).count++;}pages+=`<article class="print-sheet"><header><div><strong>BYU–IDAHO · Hart Fitness Center</strong><h2>${esc(layout().name)} · ${esc(title)}</h2></div><small>Sheet ${index+1} / ${tiles.length}<br>${fmt(tile.w)} × ${fmt(tile.h)} ft · X ${fmt(tile.x)}, Y ${fmt(tile.y)}</small></header><div class="print-map">${clone.outerHTML.replace(/id="(grid|hatch|roomClip)"/g,(_,id)=>`id="print-${index}-${id}"`).replace(/url\(#(grid|hatch|roomClip)\)/g,(_,id)=>`url(#print-${index}-${id})`)}</div><div class="print-legend"><strong>Equipment legend · ${equipment.length} pieces on this sheet</strong><div class="legend-items">${[...groups.values()].map(i=>`<span>${icon(i.kind,palette[i.category].ink)}<b>${esc(i.name)}</b><small>× ${i.count} · ${fmt(i.width)} × ${fmt(i.length)} ft</small></span>`).join('')||'<span>No floor equipment in this region.</span>'}</div><p>Black: full walls · Grey: half walls · Dashed: named areas · Dimensions in feet</p>${layout().items.some(i=>i.storedIn)?`<p>Storage inventory: ${layout().items.filter(i=>i.storedIn).map(i=>esc(i.name)+' ('+esc(layout().items.find(a=>a.id===i.storedIn)?.name||'Storage')+')').join(', ')}</p>`:''}</div></article>`;}$('printPages').innerHTML=pages;$('printDialog').close();$('printPreview').hidden=false;}catch(err){toast(err.message);}};
$('closePrintPreview').onclick=()=>$('printPreview').hidden=true;$('confirmPrint').onclick=()=>window.print();

let pendingDeleteLayout=null,storageDrag=null,inventoryQuery='',inventoryLocation='all';
$('facilitySettingsBtn').onclick=()=>{$('facilityDialog').showModal();};$('closeFacility').onclick=()=>$('facilityDialog').close();
$('cancelDeleteLayout').onclick=()=>{$('deleteLayoutDialog').close();pendingDeleteLayout=null;};
$('confirmDeleteLayout').onclick=()=>{if(!pendingDeleteLayout||project.layouts.length<2)return;const id=pendingDeleteLayout;$('deleteLayoutDialog').close();change(()=>{project.layouts=project.layouts.filter(l=>l.id!==id);if(project.active===id){project.active=project.layouts[0].id;selectOnly(null);camera={x:0,y:0};zoom=1;}project.sketchInstalled=true;});pendingDeleteLayout=null;toast('Layout deleted. Undo restores it during this session.');};
function moveSelectionToStorage(){const equipment=selectedItems().filter(isEquipment);if(!equipment.length)return toast('Select equipment on the gym map or in the list first.');change(()=>equipment.forEach(i=>storeEquipment(layout().items,i)));toast('Equipment moved to storage.');}
$('storeSelectedBtn').onclick=moveSelectionToStorage;
$('addToStorageBtn').onclick=()=>{$('addDestination').value='storage';$('equipmentLibrary').scrollIntoView({behavior:'smooth',block:'start'});toast('Choose equipment from the library to add it directly to storage.');};
$('addDestination').onchange=()=>toast($('addDestination').value==='storage'?'Library equipment will be added to storage.':'Library equipment will be added to the gym floor.');
$('inspectorContent').addEventListener('click',e=>{if(e.target.closest('[data-action]')?.dataset.action==='return-floor'){change(()=>selectedItems().filter(isEquipment).forEach(i=>delete i.storedIn));toast('Equipment returned to its last gym floor position.');}});
function renderStorage(){const stored=layout().items.filter(i=>i.storedIn&&isEquipment(i)),view=storageDrag?.view||storageView(layout().items);$('storageCount').textContent=stored.length+(stored.length===1?' piece':' pieces');$('storeSelectedBtn').disabled=!selectedItems().some(i=>isEquipment(i)&&!i.storedIn);$('storageBoard').setAttribute('viewBox',`0 0 ${view.w} ${view.h}`);$('storageBoard').innerHTML=`<defs><pattern id="storageGrid" width="1" height="1" patternUnits="userSpaceOnUse"><path d="M1 0H0V1" fill="none" stroke="#dce5ee" stroke-width=".035"/></pattern></defs><rect x=".1" y=".1" width="${view.w-.2}" height="${view.h-.2}" fill="#f6f9fc" stroke="#b7c9d9" stroke-width=".12"/><rect x="0" y="0" width="${view.w}" height="${view.h}" fill="url(#storageGrid)"/>`+stored.map(i=>{const [w,h]=size(i),p=storagePose(i),sel=selection.has(i.id);return `<g data-storage-id="${esc(i.id)}" role="button" tabindex="0" aria-label="${esc(i.name)}, in storage" aria-pressed="${sel}" transform="translate(${p.x+w/2} ${p.y+h/2})" class="storage-equipment ${i.locked?'locked':''}"><title>${esc(i.name)} · ${fmt(i.width)} × ${fmt(i.length)} ft · Storage</title><g transform="rotate(${i.rotation})">${topShape(i)}</g>${sel?`<rect x="${-w/2-.15}" y="${-h/2-.15}" width="${w+.3}" height="${h+.3}" fill="none" stroke="#0062a5" stroke-width=".14"/>`:''}<text x="0" y="${h/2+.9}" text-anchor="middle" font-size=".6" fill="#38566e" pointer-events="none">${esc(i.name)}</text></g>`;}).join('')+(stored.length?'':`<text x="${view.w/2}" y="${view.h/2-1}" text-anchor="middle" font-size="1.1" fill="#53738e">No equipment in storage</text><text x="${view.w/2}" y="${view.h/2+1}" text-anchor="middle" font-size=".65" fill="#748da2">Move equipment here or add it from the library.</text>`);}
function renderInventory(){const all=layout().items.filter(isEquipment),filtered=all.filter(i=>(inventoryLocation==='all'||(inventoryLocation==='storage')===Boolean(i.storedIn))&&i.name.toLowerCase().includes(inventoryQuery.toLowerCase()));$('inventoryCount').textContent=`${all.filter(i=>!i.storedIn).length} on floor · ${all.filter(i=>i.storedIn).length} in storage`;$('inventoryRows').innerHTML=filtered.map(i=>`<tr class="${selection.has(i.id)?'selected':''}"><td><button class="inventory-select" data-inventory-select="${esc(i.id)}">${icon(i.kind,palette[i.category].ink)}<span>${esc(i.name)}</span></button></td><td>${fmt(i.width)} × ${fmt(i.length)} ft</td><td><span class="location-pill ${i.storedIn?'stored':''}">${i.storedIn?'Storage':'Gym floor'}</span></td><td><button data-inventory-transfer="${esc(i.id)}">${i.storedIn?'Return to floor':'Move to storage'}</button></td></tr>`).join('');$('inventoryEmpty').hidden=filtered.length>0;}
$('inventorySearch').oninput=e=>{inventoryQuery=e.target.value;renderInventory();};$('inventoryLocation').onchange=e=>{inventoryLocation=e.target.value;renderInventory();};
$('inventoryRows').onclick=e=>{const selectedButton=e.target.closest('[data-inventory-select]'),transfer=e.target.closest('[data-inventory-transfer]');if(selectedButton){selectOnly(selectedButton.dataset.inventorySelect);renderInspector();renderBoard();renderStorage();renderInventory();return;}if(transfer){const i=layout().items.find(i=>i.id===transfer.dataset.inventoryTransfer);change(()=>{if(i.storedIn)delete i.storedIn;else storeEquipment(layout().items,i);});toast(i.storedIn?'Moved to storage.':'Returned to last floor position.');}};
function storagePoint(e){const p=$('storageBoard').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('storageBoard').getScreenCTM().inverse());}
$('storageBoard').addEventListener('pointerdown',e=>{if(e.button!==0)return;const id=e.target.closest('[data-storage-id]')?.dataset.storageId;if(!id){selectOnly(null);renderInspector();renderStorage();renderInventory();return;}e.preventDefault();if(e.shiftKey||e.ctrlKey||e.metaKey||$('multiToggle').checked){toggleSelected(id);renderInspector();renderBoard();renderStorage();renderInventory();return;}if(!selection.has(id))selectOnly(id);else selected=id;const i=item(),p=storagePoint(e);$('storageBoard').focus({preventScroll:true});if(!i.locked){storageDrag={pointer:e.pointerId,start:p,view:storageView(layout().items),original:JSON.stringify(project),moving:selectedItems().filter(i=>i.storedIn&&!i.locked).map(i=>({id:i.id,x:i.storageX,y:i.storageY})),started:false};$('storageBoard').setPointerCapture(e.pointerId);}else toast('Position locked. Unlock it in Details to rearrange storage.');renderInspector();renderBoard();renderStorage();renderInventory();});
$('storageBoard').addEventListener('pointermove',e=>{if(!storageDrag||storageDrag.pointer!==e.pointerId)return;const p=storagePoint(e),snap=n=>$('snapToggle').checked?Math.round(n*2)/2:n;let dx=snap(p.x-storageDrag.start.x),dy=snap(p.y-storageDrag.start.y);dx=Math.max(-Math.min(...storageDrag.moving.map(i=>i.x)),dx);dy=Math.max(-Math.min(...storageDrag.moving.map(i=>i.y)),dy);for(const old of storageDrag.moving){const i=layout().items.find(i=>i.id===old.id);i.storageX=fmtRaw(Math.min(9999,old.x+dx));i.storageY=fmtRaw(Math.min(9999,old.y+dy));}if(dx||dy)storageDrag.started=true;renderStorage();});
function endStorageDrag(e){if(!storageDrag||storageDrag.pointer!==e.pointerId)return;if(e.type==='pointercancel')project=JSON.parse(storageDrag.original);else if(storageDrag.started){undo.push(storageDrag.original);if(undo.length>60)undo.shift();redo=[];persist();}storageDrag=null;render();}
$('storageBoard').addEventListener('pointerup',endStorageDrag);$('storageBoard').addEventListener('pointercancel',endStorageDrag);
$('storageBoard').addEventListener('keydown',e=>{if(e.key!=='Enter')return;const id=e.target.closest('[data-storage-id]')?.dataset.storageId;if(!id)return;e.preventDefault();selectOnly(id);renderInspector();renderBoard();renderStorage();renderInventory();});
// Keep the second map and equipment list current after pointer-only selection changes.
$('board').addEventListener('pointerup',()=>{renderStorage();renderInventory();});
$('areasList').addEventListener('click',()=>{renderStorage();renderInventory();});
$('selectAllBtn').addEventListener('click',()=>{renderStorage();renderInventory();});$('clearSelectionBtn').addEventListener('click',()=>{renderStorage();renderInventory();});
render();persist();

document.addEventListener('keyup',e=>{if(e.key==='Escape'&&!e.target.isContentEditable&&!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)){renderStorage();renderInventory();}});
